namespace sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Models;

public class Shipment
{
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTimeOffset EstimatedDelivery { get; set; }
    public List<StatusUpdate> StatusUpdates { get; set; } = [];
}

public class StatusUpdate
{
    public DateTimeOffset Timestamp { get; set; }
    public string Description { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
}

using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Models;

namespace sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Models;

namespace sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);
    }
}

using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Models;
using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Services;

namespace sv_8806b7ac69d64a47b7355fb0c6e4e71c.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(2),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-3),
                    Description = "Package picked up",
                    Location = "New York, NY"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-2),
                    Description = "Departed sorting facility",
                    Location = "Newark, NJ"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-1),
                    Description = "Arrived at regional hub",
                    Location = "Chicago, IL"
                }
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(-1),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-5),
                    Description = "Package picked up",
                    Location = "Seattle, WA"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-3),
                    Description = "In transit",
                    Location = "Portland, OR"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-1),
                    Description = "Delivered — signed by recipient",
                    Location = "San Francisco, CA"
                }
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Out for Delivery",
            Location = "Austin, TX",
            EstimatedDelivery = DateTimeOffset.UtcNow,
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddDays(-2),
                    Description = "Package picked up",
                    Location = "Dallas, TX"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddHours(-6),
                    Description = "Arrived at local facility",
                    Location = "Austin, TX"
                },
                new StatusUpdate
                {
                    Timestamp = DateTimeOffset.UtcNow.AddHours(-1),
                    Description = "Out for delivery",
                    Location = "Austin, TX"
                }
            ]
        }
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Models
@using sv_8806b7ac69d64a47b7355fb0c6e4e71c.Client.Services
@implements IDisposable
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h1>Shipment Tracking</h1>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.LocalDateTime.ToString("f")</p>
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h4>Tracking History</h4>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.LocalDateTime.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string _lastLoadedTracking = string.Empty;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(TrackingNumber, _lastLoadedTracking, StringComparison.OrdinalIgnoreCase))
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        await CancelPendingRequestAsync();

        _lastLoadedTracking = TrackingNumber;
        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation or disposal) — don't update UI
            return;
        }
        catch (TaskCanceledException)
        {
            Logger.LogWarning("Request timed out for shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException)
        {
            Logger.LogWarning("Request timed out for shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading this shipment. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        _lastLoadedTracking = string.Empty;
        await LoadShipmentAsync();
    }

    private async ValueTask CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

